const pipeline = (x) => x();

const importers = [
  async (path) => {
    if (!/^\.[\\/](?:\.storybook(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)__stories__\/(?!\.)(?=.)[^/]*?\.stories\.(js|jsx|ts|tsx|mdx))$/.exec(path)) {
      return;
    }
  
    const pathRemainder = path.substring(13);
    return import(
      /* webpackChunkName: "[request]" */
      /* webpackInclude: /(?:\/\.storybook(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)__stories__\/(?!\.)(?=.)[^/]*?\.stories\.(js|jsx|ts|tsx|mdx))$/ */
      './.storybook/' + pathRemainder
    );
  }
  ,
  async (path) => {
    if (!/^\.[\\/](?:src(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)(?!\.)(?=.)[^/]*?\.stories\.(js|jsx|ts|tsx|mdx))$/.exec(path)) {
      return;
    }
  
    const pathRemainder = path.substring(6);
    return import(
      /* webpackChunkName: "[request]" */
      /* webpackInclude: /(?:\/src(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)(?!\.)(?=.)[^/]*?\.stories\.(js|jsx|ts|tsx|mdx))$/ */
      './src/' + pathRemainder
    );
  }
  ,
  async (path) => {
    if (!/^\.[\\/](?:\.storybook(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)(?!\.)(?=.)[^/]*?\.(mdx))$/.exec(path)) {
      return;
    }
  
    const pathRemainder = path.substring(13);
    return import(
      /* webpackChunkName: "[request]" */
      /* webpackInclude: /(?:\/\.storybook(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)(?!\.)(?=.)[^/]*?\.(mdx))$/ */
      './.storybook/' + pathRemainder
    );
  }
  
];

export async function importFn(path) {
  for (let i = 0; i < importers.length; i++) {
    const moduleExports = await pipeline(() => importers[i](path));
    if (moduleExports) {
      return moduleExports;
    }
  }
}